/* ================= Discover UI ================= */
S.ui.disc={q:'',filters:EMPTY_FILTERS(),slot:null,shown:12,loading:false,error:null,liveIds:[],liveTried:false,lastQuery:'',atHomeMax:null};
const HEART='<svg viewBox="0 0 24 24" fill="currentColor"><path d="M12 21s-7.5-4.6-9.5-9.3C1.2 8.4 3.3 5 6.8 5c1.9 0 3.4 1 4.2 2.4C11.8 6 13.3 5 15.2 5c3.5 0 5.6 3.4 4.3 6.7C17.5 16.4 12 21 12 21z"/></svg>';
const HEART_O='<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="2" stroke-linejoin="round"><path d="M12 21s-7.5-4.6-9.5-9.3C1.2 8.4 3.3 5 6.8 5c1.9 0 3.4 1 4.2 2.4C11.8 6 13.3 5 15.2 5c3.5 0 5.6 3.4 4.3 6.7C17.5 16.4 12 21 12 21z"/></svg>';
const imgState={};
function allDiscoverRecipes(){const seen=new Set();const out=[];for(const r of Object.values(S.recipes)){prepRecipe(r);seen.add(r.id);out.push(r)}for(const id of S.ui.disc.liveIds){const r=S.external[id];if(r&&!seen.has(id)&&!Object.values(S.recipes).some(x=>x.source&&x.source.externalId===r.source.externalId&&x.source.provider===r.source.provider))out.push(r)}return out}
function photoHtml(r,eager){const u=recipeImage(r);if(!u||imgState[u]==='error')return '';return `<img src="${esc(u)}" alt="${esc(recipeImageAlt(r))}" loading="${eager?'eager':'lazy'}" decoding="async" referrerpolicy="no-referrer" data-src="${esc(u)}" onerror="this.remove()">`}
function hydrateImages(){document.querySelectorAll('img[data-src]').forEach(im=>{if(im.dataset.bound)return;im.dataset.bound=1;im.addEventListener('error',()=>{imgState[im.dataset.src]='error'},{once:true})})}
function recipeCard(r,ctx,opts){opts=opts||{};const sig=recipeSignals(r,ctx);const labels=opts.why&&opts.why.length?opts.why.slice(0,2):signalLabels(r,sig);const cost=recipeCost(r);const mt=(r.mealTypes||['dinner']);const dietTags=sig.diets.filter(t=>['vegetarian','vegan','gluten-free','dairy-free','high-protein'].includes(t)).filter(t=>(r.tags||[]).includes(t)||t==='vegan'||t==='vegetarian').slice(0,2);
  return `<article class="rcard"><div class="rimg" data-action="open-recipe" data-id="${esc(r.id)}" style="background-image:url('${tileDataUrl(r)}')">${photoHtml(r)}${imageCreditHtml(r)}<div class="ovl"><span class="chip">${MEAL_LABEL[mt[0]]}</span>${r.minutes?`<span class="chip">${r.minutes} min</span>`:''}</div></div>
    <button class="fav ${r.favorite?'on':''}" data-action="fav-card" data-id="${esc(r.id)}" aria-label="${r.favorite?'Remove from favorites':'Add to favorites'}">${r.favorite?HEART:HEART_O}</button>
    <div class="body"><div class="rn" data-action="open-recipe" data-id="${esc(r.id)}">${esc(r.name)}</div>
      <div class="meta num"><span>${cost?money(cost)+' / serving':'price unknown'}</span><span>makes ${r.servings}</span>${isExternal(r)?`<span>${esc(r.source.name||'web')}</span>`:r.source&&r.source.type==='ai'?'<span>Created for you</span>':''}</div>
      ${labels.length?`<div class="sig">${labels.map(l=>`<span>${esc(l)}</span>`).join('')}</div>`:''}
      <div class="foot"><div class="tags">${dietTags.map(t=>`<span class="tag">${t}</span>`).join('')}</div><button class="btn sm primary" data-action="add-flow" data-id="${esc(r.id)}">${ICONS.plus} Add</button></div></div></article>`}
function activeFilterCount(f){f=f||S.ui.disc.filters;return ['meal','maxMinutes','maxCost','oneServing','cuisine','usesPantry','overlap','leftovers','freezer'].filter(k=>f[k]).length+(f.diet||[]).length+(f.include||[]).length+(f.exclude||[]).length}
function viewDiscover(){const d=S.ui.disc;const ctx=discoverContext();const prov=activeProvider();const all=allDiscoverRecipes();const f={...d.filters,q:d.q};const pantryMode=d.atHomeMax!=null;const searching=!!(pantryMode||d.q.trim()||activeFilterCount(d.filters));
  const slot=d.slot?`<div class="note" style="margin-bottom:14px;display:flex;justify-content:space-between;gap:10px;flex-wrap:wrap;align-items:center"><span>Choosing <b>${DAYS_LONG[d.slot.day]} ${d.slot.meal}</b>. "Add" puts the recipe straight into that slot.</span><button class="btn sm ghost" data-action="disc-clear-slot">Done choosing</button></div>`:'';
  const provNote=prov.live?(d.error?`<div class="prov err"><span>${esc(d.error)} Showing your recipe box and starter recipes meanwhile.</span><button class="btn sm" data-action="disc-retry">Retry</button></div>`:`<div class="prov live"><span>Live recipes from your recipe service${d.liveIds.length?` · ${d.liveIds.length} loaded`:''}. Recipe data and images via spoonacular.com; every recipe links to its source.</span>${d.loading?'<span class="thinking" style="padding:0"><span class="sp"></span></span>':''}</div>`)
    :`<div class="prov"><span>Browsing your recipe box and Plenty's original starter recipes. Live internet recipes switch on when a recipe service is connected in Settings.</span><button class="btn sm ghost" data-action="tab" data-tab="settings">Settings</button></div>`;
  let body='';
  if(searching){const filtered=filterRecipes(all,f,ctx);const matches=pantryMode?atHomeRecipeMatches(filtered.results,d.atHomeMax):null;const results=pantryMode?matches.map(m=>m.recipe):filtered.results;const ranked=pantryMode?matches.map(m=>({recipe:m.recipe,why:[m.missing.length?`${m.missing.length} item${m.missing.length===1?'':'s'} to buy`:'Everything is at home',`${m.have.length} ingredient${m.have.length===1?'':'s'} at home`]})):rankRecipes(results,ctx);const shown=ranked.slice(0,d.shown);
    body=`<div class="coll"><div class="ch"><div><h3>${pantryMode?'Cook from At Home':`${results.length} result${results.length===1?'':'s'}${d.q.trim()?` for “${esc(d.q.trim())}”`:''}`}</h3>${pantryMode?`<div class="sub">${results.length} recipe${results.length===1?'':'s'} with ${d.atHomeMax===0?'nothing':`up to ${d.atHomeMax} item${d.atHomeMax===1?'':'s'}`} to buy. Opening a recipe shows the exact missing items.</div>`:''}</div><span class="sub">${filtered.hiddenByAllergy?`${filtered.hiddenByAllergy} hidden by your allergy settings`:''}</span></div>
      ${d.loading?`<div class="shelf grid">${[0,1,2,3].map(()=>'<div class="skel"><div class="a"></div><div class="b"></div><div class="c"></div></div>').join('')}</div>`:''}
      ${shown.length?`<div class="shelf grid">${shown.map(x=>recipeCard(x.recipe,ctx,{why:x.why})).join('')}</div>`:!d.loading?`<div class="empty"><h3>No recipes match</h3><div>Try fewer filters, another word, or create the recipe you have in mind.</div><div class="actions"><button class="btn" data-action="disc-reset">Clear filters</button><button class="btn primary" data-action="create-chooser">Create recipe</button></div></div>`:''}
      ${results.length>d.shown?`<div class="actions" style="justify-content:center;margin-top:14px"><button class="btn" data-action="disc-more">Show more</button></div>`:''}</div>`}
  else{const cols=discoverCollections(all,ctx);const hidden=filterRecipes(all,{},ctx).hiddenByAllergy;
    body=(hidden?`<div class="small faint" style="margin:-6px 0 12px">${hidden} recipe${hidden===1?'':'s'} hidden by your allergy settings (${(S.settings.allergies||[]).join(', ')}).</div>`:'')+(d.loading?`<div class="coll"><div class="ch"><h3>Loading live recipes</h3></div><div class="shelf">${[0,1,2,3].map(()=>'<div class="skel"><div class="a"></div><div class="b"></div><div class="c"></div></div>').join('')}</div></div>`:'')
      +cols.map(c=>`<section class="coll"><div class="ch"><div><h3>${esc(c.title)}</h3>${c.sub?`<div class="sub">${esc(c.sub)}</div>`:''}</div>${c.recipes.length>8?`<button class="btn sm ghost" data-action="disc-collection" data-k="${c.key}">See all ${c.recipes.length}</button>`:''}</div><div class="shelf">${c.recipes.slice(0,8).map(r=>recipeCard(r,ctx,{why:c.why&&c.why[r.id]})).join('')}</div></section>`).join('')
      +(!cols.length?starterEmpty():'')}
  return `<div class="head"><div><div class="eyebrow">Discover</div><h1>Find your next meals</h1><div class="sub">Recipes that fit your budget, your pantry and this week's plan. Every one you add flows through the same grocery list.</div></div>
    <div class="actions"><button class="btn" data-action="url-import">Import from URL</button><button class="btn primary" data-action="create-chooser">${ICONS.plus} Create recipe</button></div></div>
  ${slot}${provNote}
  <div class="dsearch"><div class="search">${ICONS.search}<input id="dq" placeholder="Search recipes, ingredients or cuisines" value="${esc(d.q)}" data-input="dq"></div><button class="btn" data-action="disc-filters">Filters${activeFilterCount()?` · ${activeFilterCount()}`:''}</button>${searching?`<button class="btn ghost" data-action="disc-reset">Clear</button>`:''}</div>
  <div class="fchips"><button class="tag pick ${d.filters.meal==='breakfast'?'on':''}" data-action="disc-chip" data-k="meal" data-v="breakfast">Breakfast</button><button class="tag pick ${d.filters.meal==='lunch'?'on':''}" data-action="disc-chip" data-k="meal" data-v="lunch">Lunch</button><button class="tag pick ${d.filters.meal==='dinner'?'on':''}" data-action="disc-chip" data-k="meal" data-v="dinner">Dinner</button><button class="tag pick ${d.filters.maxMinutes===20?'on':''}" data-action="disc-chip" data-k="maxMinutes" data-v="20">≤ 20 min</button><button class="tag pick ${d.filters.usesPantry||pantryMode?'on':''}" data-action="at-home-recipes" data-max="3">Use what I have</button></div>
  ${body}`}
let liveTimer=null;
async function loadLive(force){const d=S.ui.disc;const prov=activeProvider();if(!prov.live)return;const key=JSON.stringify([d.q.trim(),d.filters]);if(!force&&d.lastQuery===key)return;d.lastQuery=key;d.loading=true;d.error=null;render();
  try{const f={...d.filters,q:d.q.trim(),number:12};const res=(d.q.trim()||activeFilterCount(d.filters))?await prov.search(f):await prov.featured();const ids=[];for(const r of res.results||[]){if(!r)continue;S.external[r.id]=r;ids.push(r.id)}d.liveIds=ids}
  catch(e){d.error=e.code==='quota'?'The recipe service has used its daily quota.':e.code==='timeout'?'The recipe service did not answer in time.':e.code==='network'?'The recipe service could not be reached (offline, blocked, or not running).':(e.message||'The recipe service failed.')}
  finally{d.loading=false;d.liveTried=true;render()}}
function discSearchInput(v){S.ui.disc.q=v;S.ui.disc.shown=12;clearTimeout(liveTimer);liveTimer=setTimeout(()=>{render();loadLive()},300)}
function openFilters(){const f=clone(S.ui.disc.filters);const cuisines=[...new Set(allDiscoverRecipes().map(r=>r.cuisine).filter(Boolean))].sort();
  openModal(`${mhead('Filters','Allergies from Settings are always applied and cannot be switched off here.')}<div class="mb">
    <div class="field"><label>Meal type</label><div class="mealrow">${MEAL_TYPES.map(m=>`<button type="button" class="tag pick ${f.meal===m?'on':''}" data-fk="meal" data-fv="${m}">${MEAL_LABEL[m]}</button>`).join('')}</div></div>
    <div class="row"><div class="field"><label for="fMin">Max cooking time (min)</label><input id="fMin" type="number" min="0" step="5" value="${f.maxMinutes||''}" placeholder="any"></div><div class="field"><label for="fCost">Max cost per serving (${esc(S.settings.currency)})</label><input id="fCost" type="number" min="0" step="0.5" value="${f.maxCost||''}" placeholder="any"></div><div class="field"><label for="fCui">Cuisine</label><select id="fCui"><option value="">Any</option>${cuisines.map(c=>`<option ${f.cuisine===c?'selected':''}>${esc(c)}</option>`).join('')}</select></div></div>
    <div class="field"><label>Dietary</label><div class="mealrow">${['vegetarian','vegan','high-protein','gluten-free','dairy-free'].map(t=>`<button type="button" class="tag pick ${(f.diet||[]).includes(t)?'on':''}" data-fk="diet" data-fv="${t}">${t}</button>`).join('')}</div></div>
    <div class="row"><div class="field"><label for="fInc">Must include ingredients</label><input id="fInc" value="${esc((f.include||[]).join(', '))}" placeholder="e.g. chicken, rice"></div><div class="field"><label for="fExc">Exclude ingredients</label><input id="fExc" value="${esc((f.exclude||[]).join(', '))}" placeholder="e.g. mushroom"></div></div>
    <div class="field"><label>More</label><div class="checks">${[['oneServing','Good for one'],['usesPantry','Uses pantry ingredients'],['overlap','Good overlap with this week'],['leftovers','Suitable for leftovers'],['freezer','Freezer friendly']].map(([k,l])=>`<label><input type="checkbox" data-fb="${k}" ${f[k]?'checked':''}>${l}</label>`).join('')}</div></div>
    <div class="note">Allergies enforced: ${(S.settings.allergies||[]).length?esc(S.settings.allergies.join(', ')):'none set'} · <button class="btn sm ghost" data-action="tab" data-tab="settings" style="padding:2px 6px">change in Settings</button></div></div>
    <div class="mf"><button class="btn ghost" id="fReset">Reset</button><div class="actions"><button class="btn ghost" data-close>Cancel</button><button class="btn primary" id="fApply">Show recipes</button></div></div>`);
  const box=document.querySelector('.modal');box.addEventListener('click',e=>{const b=e.target.closest('[data-fk]');if(!b)return;if(b.dataset.fk==='meal'){f.meal=f.meal===b.dataset.fv?'':b.dataset.fv;box.querySelectorAll('[data-fk="meal"]').forEach(x=>x.classList.toggle('on',x.dataset.fv===f.meal))}else{const set=new Set(f.diet||[]);set.has(b.dataset.fv)?set.delete(b.dataset.fv):set.add(b.dataset.fv);f.diet=[...set];b.classList.toggle('on')}});
  const read=()=>{f.maxMinutes=parseFloat(document.getElementById('fMin').value)||0;f.maxCost=parseFloat(document.getElementById('fCost').value)||0;f.cuisine=document.getElementById('fCui').value;f.include=document.getElementById('fInc').value.split(',').map(s=>s.trim()).filter(Boolean);f.exclude=document.getElementById('fExc').value.split(',').map(s=>s.trim()).filter(Boolean);box.querySelectorAll('[data-fb]').forEach(cb=>f[cb.dataset.fb]=cb.checked);return f};
  document.getElementById('fApply').onclick=()=>{S.ui.disc.filters=read();S.ui.disc.shown=12;closeModal();render();loadLive()};document.getElementById('fReset').onclick=()=>{S.ui.disc.filters=EMPTY_FILTERS();closeModal();render();loadLive()}}

/* ================= recipe detail ================= */
function openRecipe(id,opts){opts=opts||{};let r=getRecipe(id);if(!r)return;prepRecipe(r);let sv=opts.servings||S.settings.people||1;noteViewed(id);
  if(isExternal(r)&&!S.recipes[id]&&activeProvider().live&&(!r.steps||!r.steps.length)&&!r._detailed){activeProvider().details(id).then(full=>{if(full){full._detailed=true;S.external[id]=full;if(modalOpen()&&document.querySelector('.modal[data-recipe="'+id+'"]'))openRecipe(id,{servings:sv})}}).catch(()=>{})}
  const draw=()=>{const ctx=discoverContext();const sig=recipeSignals(r,ctx);const scale=sv/(r.servings||1);const cps=recipeCost(r);const inv=ctx.inv;const weekLines=ctx.B.lines;
    const groups={home:[],buy:[],shared:[]};for(const i of (r.ingredients||[])){const cn=canon(i.name);const line=weekLines.find(l=>l.canon===cn);if(inv[cn])groups.home.push(i);else groups.buy.push(i);if(line&&line.recipes.length&&!line.recipes.includes(r.id))groups.shared.push(i)}
    const slot=opts.slot||S.ui.disc.slot||null;const defMeal=slot?slot.meal:(r.mealTypes||['dinner'])[0];let defDay=slot?slot.day:-1;if(defDay<0){for(let d=0;d<7;d++)if(!slotEntries(week(),d,defMeal).length){defDay=d;break}if(defDay<0)defDay=((today()-parseISO(S.ui.weekKey))/86400000|0)%7;if(defDay<0||defDay>6)defDay=0}
    const sim=simulateAdd(defDay,defMeal,r,sv,true);const src=r.source||{};const srcLabel=src.type==='external'?`${esc(src.name||'web')}`:src.type==='import'?`Imported from ${esc(src.name||'the web')}`:src.type==='ai'?'Created for you by Claude':src.type==='starter'?'Plenty starter recipe':'My recipes';
    document.getElementById('modal').innerHTML=`<div class="overlay"><div class="modal wide" role="dialog" aria-modal="true" data-recipe="${esc(id)}" style="max-height:94vh">
      <div class="rhero" style="background-image:url('${tileDataUrl(r)}')">${photoHtml(r,true)}${imageCreditHtml(r)}<button class="btn icon close" data-close aria-label="Close">${ICONS.x}</button><span class="src">${srcLabel}</span></div>
      <div class="mb" style="padding-top:14px">
        <div style="display:flex;justify-content:space-between;gap:12px;align-items:flex-start;flex-wrap:wrap"><div><h2 style="font-size:24px">${esc(r.name)}</h2>${r.description?`<p class="muted" style="margin-top:6px;max-width:60ch">${esc(r.description)}</p>`:''}</div><button class="btn ${r.favorite?'primary':''}" data-action="fav-card" data-id="${esc(id)}">${r.favorite?HEART:HEART_O} ${r.favorite?'Favorite':'Favorite'}</button></div>
        <div class="facts num">${r.prepMinutes!=null?`<span>Prep <b>${r.prepMinutes} min</b></span>`:''}${r.cookMinutes!=null?`<span>Cook <b>${r.cookMinutes} min</b></span>`:''}<span>Total <b>${r.minutes||'?'} min</b></span><span>Per serving <b>${cps?money(cps):'—'}</b></span><span>${sv} serving${sv===1?'':'s'} <b>${cps?money(cps*sv):'—'}</b></span>${r.cuisine?`<span>${esc(r.cuisine)}</span>`:''}</div>
        <div style="display:flex;gap:6px;flex-wrap:wrap">${(r.mealTypes||[]).map(m=>`<span class="chip acc">${MEAL_LABEL[m]}</span>`).join('')}${sig.diets.filter(t=>['vegetarian','vegan','gluten-free','dairy-free','high-protein'].includes(t)).map(t=>`<span class="tag">${t}</span>`).join('')}${sig.allergens.length?`<span class="tag" style="background:var(--warn-soft);color:var(--warn)">contains ${esc(sig.allergens.join(', '))}</span>`:'<span class="tag">no common allergens detected</span>'}${sig.freezer?'<span class="tag">freezer friendly</span>':''}</div>
        <div style="display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap"><h3>Ingredients</h3><span class="stepper"><button data-rs="-1" aria-label="Fewer servings">−</button><span>${sv} serving${sv===1?'':'s'}</span><button data-rs="1" aria-label="More servings">+</button></span></div>
        <ul class="ingl">${(r.ingredients||[]).map(i=>{const cn=canon(i.name);const home=!!inv[cn];return `<li><span class="q num">${esc(fmtQty((+i.qty||0)*scale,i.unit))}</span><span>${esc(i.name)}${home?' <span class="chip good" style="font-size:10.5px;padding:0 6px">at home</span>':''}</span>${+i.price>0?`<span class="faint num" style="margin-left:auto">${money(+i.price*scale)}</span>`:''}</li>`}).join('')}</ul>
        <div class="split"><div class="card"><div class="eyebrow">Already at home</div>${groups.home.length?`<ul>${groups.home.map(i=>`<li>${esc(i.name)}</li>`).join('')}</ul>`:'<div class="small faint">Nothing from this recipe is in At Home.</div>'}</div><div class="card"><div class="eyebrow">Need to buy</div>${groups.buy.length?`<ul>${groups.buy.map(i=>`<li>${esc(i.name)}</li>`).join('')}</ul>`:'<div class="small faint">Everything is at home.</div>'}</div><div class="card"><div class="eyebrow">Shared with your week</div>${groups.shared.length?`<ul>${groups.shared.map(i=>`<li>${esc(i.name)}</li>`).join('')}</ul>`:'<div class="small faint">No overlap with planned recipes yet.</div>'}</div></div>
        ${(r.steps||[]).length?`<h3>Method</h3><ol class="steps">${r.steps.map(s=>`<li>${esc(s)}</li>`).join('')}</ol>`:src.url?`<div class="note">The method is on the original page: <a href="${esc(src.url)}" target="_blank" rel="noopener">${esc(src.name||src.url)}</a></div>`:'<div class="note">No method recorded yet. Edit the recipe to add steps.</div>'}
        ${r.nutrition&&(r.nutrition.kcal||r.nutrition.protein)?`<h3>Nutrition per serving</h3><div class="ntiles num"><div class="nt"><b>${r.nutrition.kcal||0}</b><span>kcal</span></div><div class="nt"><b>${r.nutrition.protein||0}g</b><span>protein</span></div><div class="nt"><b>${r.nutrition.carbs||0}g</b><span>carbs</span></div><div class="nt"><b>${r.nutrition.fat||0}g</b><span>fat</span></div></div><div class="small faint" style="margin-top:-8px">${r.nutritionEstimated?'Estimated by Claude; treat as a guide.':'From the recipe source.'}</div>`:'<div class="small faint">Nutrition not reliably available for this recipe.</div>'}
        ${(r.storage||r.leftovers||r.notes)?`<div class="split">${r.storage?`<div class="card"><div class="eyebrow">Storage</div><div class="small">${esc(r.storage)}</div></div>`:''}${r.leftovers?`<div class="card"><div class="eyebrow">Leftovers</div><div class="small">${esc(r.leftovers)}</div></div>`:''}${r.notes?`<div class="card"><div class="eyebrow">Notes</div><div class="small">${esc(r.notes)}</div></div>`:''}</div>`:''}
        <div class="impact"><div class="eyebrow" style="margin-bottom:6px">Budget impact if added to ${DAYS_LONG[defDay]} ${defMeal} (${sv} serving${sv===1?'':'s'})</div>
          <div class="kv"><span>Adds to the grocery list</span><b class="num">${sim.delta>=0?'+':'−'}${money(Math.abs(sim.delta))}</b></div><div class="kv"><span>New checkout estimate</span><b class="num">${money(sim.after.actual)}</b></div><div class="kv"><span>${sim.after.remaining>=0?'Remaining after buffer':'Over budget by'}</span><b class="num" style="color:${sim.after.remaining>=0?'var(--good)':'var(--bad)'}">${money(Math.abs(sim.after.remaining))}</b></div>
          <div class="small muted" style="margin-top:4px">${sim.newLines.length} new line${sim.newLines.length===1?'':'s'} to buy · ${sim.atHome.length} covered by At Home · ${sim.shared.length} merged with other lines</div>${sim.warning?`<div class="note ${sim.overBy>0?'bad':'warn'}" style="margin-top:8px">${esc(sim.warning)}</div>`:''}</div>
        <div class="small faint">Source: ${srcLabel}${src.url?` · <a href="${esc(src.url)}" target="_blank" rel="noopener">open original</a>`:''}${src.attribution?` · ${esc(src.attribution)}`:''}${src.type==='ai'?' · generated for you, not taken from a website':''}</div>
      </div>
      <div class="mf"><div class="actions" style="margin-left:0"><button class="btn ghost" data-action="add-missing" data-id="${esc(id)}" data-sv="${sv}" title="Add the ingredients you lack to this week's list without planning the meal">Add missing to groceries</button><button class="btn ghost ai-only" data-action="ai-similar" data-id="${esc(id)}">${ICONS.spark} Similar recipe</button><button class="btn ghost ai-only" data-action="ask-coach" data-id="${esc(id)}">Ask Plenty</button>${S.recipes[id]?`<button class="btn ghost" data-action="edit-recipe" data-id="${esc(id)}">Edit</button><button class="btn ghost" data-action="cooked" data-id="${esc(id)}">Cooked it</button><button class="btn ghost danger" data-action="hide-recipe" data-id="${esc(id)}" title="Never recommend again">Hide</button>`:''}</div><div class="actions"><button class="btn primary" data-action="add-flow" data-id="${esc(id)}" data-sv="${sv}">Add to plan</button></div></div></div></div>`;
    document.querySelectorAll('[data-rs]').forEach(b=>b.onclick=()=>{sv=Math.max(1,Math.min(12,sv+ +b.dataset.rs));draw()});hydrateImages()};
  draw()}

/* ================= add to plan flow ================= */
function ensureSaved(r){if(S.recipes[r.id])return S.recipes[r.id];const c=clone(r);delete c._detailed;c.createdAt=Date.now();S.recipes[c.id]=c;writeDoc('recipes/'+c.id,c);return c}
function openAddFlow(id,pre){const r=getRecipe(id);if(!r)return;pre=pre||{};const slot=pre.slot||S.ui.disc.slot;const st={day:slot?slot.day:(pre.day!=null?pre.day:-1),meal:slot?slot.meal:(pre.meal||(r.mealTypes||['dinner'])[0]),sv:pre.sv||S.settings.people||1,postpone:[],replaceEntry:null,week:'this'};
  if(st.day<0){for(let d=0;d<7;d++)if(!slotEntries(week(),d,st.meal).length){st.day=d;break}if(st.day<0)st.day=0}
  const draw=()=>{const sim=simulateAdd(st.day,st.meal,r,st.sv,true,{postpone:st.postpone});const cur=slotEntries(week(),st.day,st.meal);const multi=['snack','drink','treat'].includes(st.meal);const replacing=cur.length&&!multi;
    document.getElementById('modal').innerHTML=`<div class="overlay"><div class="modal" role="dialog" aria-modal="true">${mhead('Add to plan',esc(r.name))}<div class="mb">
      <div class="field"><label>Day</label><div class="dayrow">${DAYS.map((d,i)=>{const dt=addDays(parseISO(S.ui.weekKey),i);const has=slotEntries(week(),i,st.meal).length;return `<button type="button" class="${st.day===i?'on':''}" data-day="${i}">${d}<small>${has?'●':fmtDate(dt).split(' ')[0]}</small></button>`}).join('')}</div></div>
      <div class="field"><label>Meal type</label><div class="mealrow">${activeMeals().map(m=>`<button type="button" class="tag pick ${st.meal===m?'on':''}" data-meal="${m}">${MEAL_LABEL[m]}${(r.mealTypes||[]).includes(m)?'':' ·'}</button>`).join('')}</div></div>
      <div style="display:flex;justify-content:space-between;align-items:center;gap:10px;flex-wrap:wrap"><label class="small" style="font-weight:600;color:var(--ink2)">Servings to cook</label><span class="stepper"><button data-sv="-1" aria-label="Fewer">−</button><span>${st.sv}</span><button data-sv="1" aria-label="More">+</button></span></div>
      ${replacing?`<div class="note warn">${DAYS_LONG[st.day]} ${st.meal} already has <b>${esc(cur.map(e=>e.t==='r'?(S.recipes[e.id]||{}).name:e.t==='l'?'leftovers':(S.items[e.id]||{}).name).join(', '))}</b>. Adding here replaces it.</div>`:''}
      <div class="impact"><div class="eyebrow" style="margin-bottom:6px">Summary</div>
        <div class="kv"><span>${DAYS_LONG[st.day]} · ${MEAL_LABEL[st.meal]} · ${st.sv} serving${st.sv===1?'':'s'}</span><b class="num">${money(sim.recipeCostTotal)}</b></div>
        <div class="kv"><span>New ingredients required</span><b class="num">${sim.newLines.length}${sim.newLines.length?` <span class="faint small" style="font-weight:400">${esc(sim.newLines.slice(0,4).map(l=>l.name).join(', '))}${sim.newLines.length>4?'…':''}</span>`:''}</b></div>
        <div class="kv"><span>Already at home</span><b class="num">${sim.atHome.length}</b></div><div class="kv"><span>Reused elsewhere this week</span><b class="num">${sim.shared.filter(l=>l.recipes.length>=2).length}</b></div>
        <div class="kv total"><span>New estimated checkout</span><b class="num">${money(sim.after.actual)} <span class="faint small" style="font-weight:400">(${sim.delta>=0?'+':'−'}${money(Math.abs(sim.delta))})</span></b></div>
        <div class="kv"><span>${sim.after.remaining>=0?'Remaining weekly budget':'Over weekly budget'}</span><b class="num" style="color:${sim.after.remaining>=0?'var(--good)':'var(--bad)'}">${money(Math.abs(sim.after.remaining))}</b></div>
        ${st.postpone.length?`<div class="small muted">Also postponing: ${esc(st.postpone.map(i=>(S.items[i]||{}).name).join(', '))}</div>`:''}
        ${sim.warning?`<div class="note ${sim.overBy>0?'bad':'warn'}" style="margin-top:8px">${esc(sim.warning)} You stay in control; here are ways to make it fit:</div>
          <div class="opts">${sim.options.cheaper.length?`<button class="btn sm" data-opt="cheaper">Use a cheaper option</button>`:''}${sim.options.reducePortions?`<button class="btn sm" data-opt="portions">Reduce to ${S.settings.people||1} portion${(S.settings.people||1)===1?'':'s'}</button>`:''}${sim.options.replace.length?`<button class="btn sm" data-opt="replace">Replace another planned recipe</button>`:''}${sim.options.removeOptional.length?`<button class="btn sm" data-opt="optional">Remove an optional grocery item</button>`:''}<button class="btn sm" data-opt="next">Save it for next week</button></div><div id="optBox"></div>`:''}
      </div></div>
      <div class="mf"><button class="btn ghost" data-close>Cancel</button><div class="actions"><button class="btn primary" id="addConfirm">${st.week==='next'?'Add to next week':replacing?'Replace and add':'Add to plan'}</button></div></div></div></div>`;
    const box=document.querySelector('.modal');
    box.querySelectorAll('[data-day]').forEach(b=>b.onclick=()=>{st.day=+b.dataset.day;draw()});box.querySelectorAll('[data-meal]').forEach(b=>b.onclick=()=>{st.meal=b.dataset.meal;draw()});box.querySelectorAll('[data-sv]').forEach(b=>b.onclick=()=>{st.sv=Math.max(1,Math.min(12,st.sv+ +b.dataset.sv));draw()});
    box.querySelectorAll('[data-opt]').forEach(b=>b.onclick=()=>{const o=document.getElementById('optBox');const k=b.dataset.opt;
      if(k==='portions'){st.sv=S.settings.people||1;draw();return}if(k==='next'){st.week='next';toast('Will be added to next week instead');draw();return}
      if(k==='cheaper'){o.innerHTML=`<div class="picker" style="margin-top:8px">${sim.options.cheaper.map(x=>`<button class="pick" data-swap="${esc(x.id)}"><span class="rn">${esc(x.name)}</span><span class="m num">${money(recipeCost(x))}/serving · ${x.minutes} min</span></button>`).join('')}</div>`;o.querySelectorAll('[data-swap]').forEach(p=>p.onclick=()=>{closeModal();openAddFlow(p.dataset.swap,{day:st.day,meal:st.meal,sv:st.sv})})}
      if(k==='replace'){o.innerHTML=`<div class="picker" style="margin-top:8px">${sim.options.replace.map((e,i)=>`<button class="pick" data-rep="${i}"><span class="rn">${esc(e.recipe.name)}</span><span class="m num">${DAYS[e.day]} ${e.meal} · ${money(e.cost)}</span></button>`).join('')}</div>`;o.querySelectorAll('[data-rep]').forEach(p=>p.onclick=()=>{const e=sim.options.replace[+p.dataset.rep];st.day=e.day;st.meal=e.meal;draw()})}
      if(k==='optional'){o.innerHTML=`<div class="picker" style="margin-top:8px">${sim.options.removeOptional.filter(c=>c.line.items.length&&!st.postpone.includes(c.line.items[0].id)).map(c=>`<button class="pick plain" data-pp="${esc(c.line.items[0].id)}"><span class="rn">${esc(c.line.name)}</span><span class="m num">${c.prio} · saves ${money(c.line.cost)}</span></button>`).join('')||'<div class="small faint">Only essentials are left on the list.</div>'}</div>`;o.querySelectorAll('[data-pp]').forEach(p=>p.onclick=()=>{st.postpone.push(p.dataset.pp);draw()})}});
    document.getElementById('addConfirm').onclick=()=>{const saved=ensureSaved(r);const targetKey=st.week==='next'?iso(addDays(parseISO(S.ui.weekKey),7)):S.ui.weekKey;const wk=week(targetKey);addEntry(st.day,st.meal,{t:'r',id:saved.id,sv:st.sv},true,wk);if(st.week!=='next'){wk.buy=wk.buy||{};for(const i of st.postpone)wk.buy[i]=false}saveWeek(targetKey);closeModal();
      if(S.ui.disc.slot)S.ui.disc.slot=null;toast(`${saved.name} added to ${DAYS_LONG[st.day]} ${st.meal}${st.week==='next'?' next week':''}. Grocery list updated.`);if(pre.thenPlan!==false&&st.week!=='next'){S.ui.tab='plan';renderNav()}render()}};
  draw()}
function addMissingToGroceries(id,sv){const r=getRecipe(id);if(!r)return;const inv=invIndex();const wk=week();wk.extras=wk.extras||[];let n=0;const scale=(sv||S.settings.people||1)/(r.servings||1);for(const i of (r.ingredients||[])){if(inv[canon(i.name)])continue;wk.extras.push({id:uid('x'),name:i.name,qty:Math.round((+i.qty||0)*scale*100)/100,unit:i.unit||'',category:i.category||guessCat(i.name),price:Math.round((+i.price||0)*scale*100)/100,priority:'preferred',fromRecipe:r.id});n++}saveWeek();toast(n?`${n} ingredient${n===1?'':'s'} added to this week's list`:'Everything is already at home')}

/* ================= create: manual / URL / AI ================= */
function openCreateChooser(slot){openModal(`${mhead('Create a recipe','Three ways in. Everything ends in the same editor so you can check quantities and prices.')}<div class="mb picker">
  <button class="pick" data-action="new-recipe" ${slot?`data-day="${slot.day}" data-meal="${slot.meal}"`:''}><span class="rn">Enter manually</span><span class="m">type ingredients and steps</span></button>
  <button class="pick" data-action="url-import" ${slot?`data-day="${slot.day}" data-meal="${slot.meal}"`:''}><span class="rn">Import from URL</span><span class="m">a recipe page you found online</span></button>
  <button class="pick ai-only" style="display:flex" data-action="ai-create" ${slot?`data-day="${slot.day}" data-meal="${slot.meal}"`:''}><span class="rn">${ICONS.spark} Create with AI</span><span class="m">describe what you want; clearly labelled as generated</span></button>
  ${sampleFn?'':'<div class="small faint">AI creation appears when Claude is available on this page.</div>'}</div><div class="mf"><button class="btn ghost" data-close>Cancel</button></div>`,'narrow')}
function openAiCreate(slot){const s=S.settings;openModal(`${mhead('Create with AI','Claude drafts a structured recipe from your brief. It is validated, then you review prices and quantities before saving. Labelled as created for you.')}<div class="mb">
    <div class="row"><div class="field"><label for="cMeal">Meal type</label><select id="cMeal">${MEAL_TYPES.map(m=>`<option value="${m}" ${(slot&&slot.meal===m)||(!slot&&m==='dinner')?'selected':''}>${MEAL_LABEL[m]}</option>`).join('')}</select></div><div class="field"><label for="cServ">Servings</label><input id="cServ" type="number" min="1" max="12" value="${s.people||1}"></div><div class="field"><label for="cTime">Max prep + cook (min)</label><input id="cTime" type="number" min="5" step="5" value="30"></div></div>
    <div class="row"><div class="field"><label for="cBud">Budget per serving (${esc(s.currency)})</label><input id="cBud" type="number" min="0" step="0.5" value="${Math.round(discoverContext().threshold*2)/2}"></div><div class="field"><label for="cCui">Cuisine</label><input id="cCui" placeholder="any, or e.g. Thai"></div><div class="field"><label for="cNut">Nutrition preference</label><select id="cNut"><option value="">Balanced</option><option>High protein</option><option>Lower calorie</option><option>High fibre</option><option>Comfort food</option></select></div></div>
    <div class="row"><div class="field"><label for="cUse">Ingredients to use</label><input id="cUse" placeholder="e.g. spinach, eggs (what you have)"></div><div class="field"><label for="cNo">Ingredients to avoid</label><input id="cNo" placeholder="e.g. mushrooms"></div></div>
    <div class="field"><label for="cDiet">Dietary requirements</label><input id="cDiet" value="${esc((s.allergies||[]).length?'no '+s.allergies.join(', no '):'')}" placeholder="e.g. vegetarian, gluten-free"></div>
    ${s.diet?`<div class="small faint">Your standing preferences are included: “${esc(s.diet.slice(0,120))}${s.diet.length>120?'…':''}”</div>`:''}<div id="aiOut"></div></div>
    <div class="mf"><button class="btn ghost" data-close>Cancel</button><div class="actions"><button class="btn ghost" id="aiStop" hidden>Stop</button><button class="btn primary" id="aiGo">${ICONS.spark} Draft recipe</button></div></div>`);
  let ctl=null;document.getElementById('aiStop').onclick=()=>ctl&&ctl.abort();
  document.getElementById('aiGo').onclick=async()=>{if(!sampleFn)return;const g=id=>document.getElementById(id).value.trim();const out=document.getElementById('aiOut'),go=document.getElementById('aiGo'),stop=document.getElementById('aiStop');out.innerHTML='<div class="thinking"><span class="sp"></span>Drafting…</div>';go.disabled=true;stop.hidden=false;ctl=new AbortController();
    const inv=Object.values(S.inventory).map(v=>v.name).slice(0,25).join(', ');
    const prompt=`Create one original home-cook recipe.\nMeal type: ${g('cMeal')}. Servings: ${g('cServ')}. Maximum total time: ${g('cTime')} minutes. Target cost per serving: ${s.currency}${g('cBud')} at typical supermarket prices${s.store?' ('+s.store+')':''}.\n${g('cCui')?'Cuisine: '+g('cCui')+'.\n':''}${g('cNut')?'Nutrition preference: '+g('cNut')+'.\n':''}${g('cUse')?'Use these ingredients: '+g('cUse')+'.\n':''}${g('cNo')?'Avoid: '+g('cNo')+'.\n':''}${g('cDiet')?'Dietary requirements (strict): '+g('cDiet')+'.\n':''}${(s.allergies||[]).length?'ALLERGIES, never include: '+s.allergies.join(', ')+'.\n':''}${s.diet?'Standing preferences: '+s.diet+'\n':''}${inv?'Already at home (prefer using): '+inv+'\n':''}Use metric units and realistic quantities. Include a one-sentence description, storage guidance and a leftover tip in notes.\n\n${RECIPE_SHAPE().replace('"notes":string (leftover or storage tip, may be empty)','"description":string,"storage":string,"leftovers":string,"cuisine":string,"freezerFriendly":boolean,"notes":string')}`;
    try{const j=await sampleFn.json(prompt,{signal:ctl.signal,cache:false});const r=coerceRecipe(j);r.description=String(j.description||'').slice(0,280);r.storage=String(j.storage||'');r.leftovers=String(j.leftovers||'');r.cuisine=String(j.cuisine||g('cCui')||'');r.freezerFriendly=!!j.freezerFriendly;r.source={type:'ai',name:'Created for you by Claude',createdAt:Date.now()};const viol=violatesAllergies(r);
      if(viol.length){out.innerHTML=`<div class="note bad">The draft contained ${esc(viol.join(', '))}, which is on your allergy list, so it was not saved. Try again with a different brief.</div>`;return}
      closeModal();openEditor(r,{sub:'Review, then save',notice:'Created for you by Claude from your brief. It is not from a website. Check quantities and prices before saving.',then:slot?saved=>{addEntry(slot.day,slot.meal,{t:'r',id:saved.id,sv:S.settings.people||1},true);saveWeek();S.ui.tab='plan';renderNav();render()}:null})}
    catch(e){if(e&&e.code==='cancelled')out.innerHTML='';else out.innerHTML=`<div class="note bad">${aiErr(e)}</div>`}finally{go.disabled=false;stop.hidden=true}}}
function openUrlImport(slot){const prov=activeProvider();
  openModal(`${mhead('Import a recipe from a URL','Only Schema.org recipe data is used, and the source name and link are kept with the recipe.')}<div class="mb">
    <div class="field"><label for="uUrl">Recipe page address</label><input id="uUrl" type="url" placeholder="https://…" inputmode="url"></div>
    ${prov.live?'<div class="small faint">The page is fetched by your recipe service, not by this browser.</div>':`<div class="note">This copy of Plenty cannot fetch websites itself (the published page has no internet access). Two ways that work here:<br>1. Open the page, select all (Ctrl/Cmd+A), copy, and paste the text below. Claude structures it and keeps the link as the source.<br>2. Paste the page source (View source → copy) and Plenty reads the Schema.org recipe data directly, no AI needed.</div><div class="field"><label for="uPaste">Pasted recipe text or page source</label><textarea id="uPaste" style="min-height:140px" placeholder="Paste here"></textarea></div>`}
    <div id="uOut"></div></div>
    <div class="mf"><button class="btn ghost" data-close>Cancel</button><div class="actions"><button class="btn" data-action="new-recipe" ${slot?`data-day="${slot.day}" data-meal="${slot.meal}"`:''}>Enter manually instead</button><button class="btn primary" id="uGo">Import</button></div></div>`);
  const then=slot?saved=>{addEntry(slot.day,slot.meal,{t:'r',id:saved.id,sv:S.settings.people||1},true);saveWeek();S.ui.tab='plan';renderNav();render()}:null;
  const finish=(parsed,src)=>{const {recipe,partial,missing}=parsed;if(!recipe){document.getElementById('uOut').innerHTML=`<div class="note bad">Import did not succeed: ${esc(missing.join(' and '))} ${missing.length===1?'is':'are'} missing from the page's recipe data${partial&&partial.name?` (found: “${esc(partial.name)}”)`:''}. Enter it manually, or paste the recipe text for Claude to structure.</div>`;return}
    closeModal();openEditor(recipe,{sub:'Review the import, then save',notice:`Imported from ${esc(src&&src.name||recipe.source.name||'the web')}${missing.length?`. Missing from the page: ${esc(missing.join(', '))}; add them below.`:'. Check quantities, units, categories and prices.'}`,then})};
  document.getElementById('uGo').onclick=async()=>{const url=document.getElementById('uUrl').value.trim();const out=document.getElementById('uOut');const paste=document.getElementById('uPaste')?document.getElementById('uPaste').value.trim():'';
    let host='';try{host=new URL(url).hostname.replace(/^www\./,'')}catch(e){}
    if(paste){const nodes=extractJsonLd(paste);if(nodes.length){finish(parseJsonLdRecipe(nodes[0],{name:host||'pasted page',url}),{name:host||'pasted page'});return}
      if(!sampleFn){out.innerHTML='<div class="note bad">No Schema.org recipe data was found in the pasted text, and Claude is not available here to structure plain text. Enter it manually.</div>';return}
      out.innerHTML='<div class="thinking"><span class="sp"></span>Structuring the pasted recipe…</div>';
      try{const j=await sampleFn.json(`Convert this recipe text into structured data. Keep the author's ingredients and steps faithfully; normalise to metric where weights or volumes are given, otherwise use pcs. Estimate per-ingredient prices in ${S.settings.currency} and nutrition per serving only if the text does not give them.\n\n${RECIPE_SHAPE()}\n\nRECIPE TEXT:\n${paste.slice(0,20000)}`,{cache:false});const r=coerceRecipe(j);r.source={type:'import',name:host||'pasted text',url,importedAt:Date.now(),via:'text'};closeModal();openEditor(r,{sub:'Review the import, then save',notice:`Structured by Claude from text you pasted${host?' from '+esc(host):''}. Check it before saving.`,then})}
      catch(e){out.innerHTML=`<div class="note bad">${aiErr(e)}</div>`}return}
    if(!url){out.innerHTML='<div class="note bad">Paste a web address first.</div>';return}
    if(!prov.live){out.innerHTML='<div class="note bad">This copy cannot fetch that page. Paste the recipe text or page source above instead.</div>';return}
    out.innerHTML='<div class="thinking"><span class="sp"></span>Fetching the page…</div>';
    try{const res=await prov.importUrl(url);if(res.error){out.innerHTML=`<div class="note bad">${esc(res.error)} You can paste the recipe text instead, or enter it manually.</div>`;return}finish(parseJsonLdRecipe(res.jsonld[0],res.source),res.source)}
    catch(e){out.innerHTML=`<div class="note bad">${esc(e.message||'The import failed.')} Try again, or enter the recipe manually.</div>`}}}

/* ================= receipts ================= */
function openLogShop(amount){const t=today();const B=budgetSummary();
  openModal(`${mhead('Log checkout','Record what you actually paid. Several trips in one week add up to the weekly total.')}<form class="mb" id="shopForm">
    <div class="row"><div class="field"><label for="tDate">Shopping date</label><input id="tDate" type="date" value="${iso(t)}" required></div><div class="field"><label for="tStore">Store</label><input id="tStore" value="${esc(S.settings.store||'')}" placeholder="e.g. Aldi" list="storeList"><datalist id="storeList">${[...new Set(Object.values(S.weeks).flatMap(w=>(w.trips||[]).map(x=>x.store)).filter(Boolean))].map(s=>`<option value="${esc(s)}">`).join('')}</datalist></div></div>
    <div class="row"><div class="field"><label for="tAmt">Actual total (${esc(S.settings.currency)})</label><input id="tAmt" type="number" step="0.01" min="0" value="${amount||''}" placeholder="0.00" required></div><div class="field"><label for="tTax">Tax included</label><input id="tTax" type="number" step="0.01" min="0" placeholder="0.00"></div><div class="field"><label for="tDisc">Discounts</label><input id="tDisc" type="number" step="0.01" min="0" placeholder="0.00"></div></div>
    <div class="field"><label for="tNote">Notes</label><input id="tNote" placeholder="optional"></div>
    ${!db?`<div class="field"><label for="tPhoto">Receipt photo <span class="faint" style="font-weight:400">optional, kept only on this device, removable</span></label><input id="tPhoto" type="file" accept="image/*" capture="environment" style="${fieldCss}"></div>`:''}
    <label class="checks" style="display:flex"><input type="checkbox" id="tMark" checked> Mark every ticked list item as bought (updates stock and pet supplies)</label>
    <div class="small faint">Estimate for this week: ${money(B.actual)}${B.spent?` · already logged ${money(B.spent)}`:''}. The estimate is kept for comparison.</div></form>
    <div class="mf"><span class="actions" style="margin-left:0">${sampleFn?`<button class="btn ai-only" data-action="receipt-scan">${ICONS.spark} Scan a receipt</button>`:'<span class="small faint">Automatic receipt reading needs a secure AI service and is not available in this version.</span>'}<button class="btn" data-action="receipt-manual">Enter line items</button></span><div class="actions"><button class="btn ghost" data-close>Cancel</button><button class="btn primary" type="submit" form="shopForm">Save trip</button></div></div>`);
  document.getElementById('shopForm').onsubmit=async e=>{e.preventDefault();const g=id=>document.getElementById(id).value;const amt=parseFloat(g('tAmt'));if(!g('tDate')||isNaN(amt))return;
    const trip={id:uid('t'),date:g('tDate'),store:g('tStore').trim(),amount:Math.round(amt*100)/100,tax:parseFloat(g('tTax'))||0,discount:parseFloat(g('tDisc'))||0,note:g('tNote').trim(),method:'quick',estimateAtTime:Math.round(B.actual*100)/100};
    const ph=document.getElementById('tPhoto');if(ph&&ph.files&&ph.files[0]&&Store.backend&&Store.profileId){try{const imgId=uid('img');await Store.putBlob(imgId,ph.files[0],{tripId:trip.id});trip.imageId=imgId}catch(err){console.warn(err);toast('The photo could not be stored; the trip is saved without it.')}}
    if(document.getElementById('tMark').checked)for(const l of buildList())if(l.checked)markBought(l,trip.date);saveTrip(trip);closeModal();toast('Trip saved')}}
async function openTripPhoto(tripId){const wk=week();const tr=(wk.trips||[]).find(t=>t.id===tripId);if(!tr||!tr.imageId)return;const rec=await Store.getBlob(tr.imageId);if(!rec||!rec.blob){toast('The photo is no longer stored.');return}const url=URL.createObjectURL(rec.blob);openModal(`${mhead('Receipt photo',`${esc(tr.store||'Shop')} · ${fmtDate(parseISO(tr.date))} · stored only on this device`)}<div class="mb"><img src="${url}" alt="Receipt" style="max-width:100%;border-radius:8px">${typeof accountPhotoControlsHtml==='function'?accountPhotoControlsHtml(tr):''}</div><div class="mf"><button class="btn ghost danger" data-action="trip-photo-remove" data-id="${esc(tr.id)}">Remove photo</button><div class="actions"><button class="btn" data-close>Close</button></div></div>`);const ov=document.querySelector('.overlay');if(ov)ov.addEventListener('click',()=>setTimeout(()=>URL.revokeObjectURL(url),500),{once:true})}
async function removeTripPhoto(tripId){for(const k in S.weeks){const tr=(S.weeks[k].trips||[]).find(t=>t.id===tripId);if(tr&&tr.imageId){try{await Store.delBlob(tr.imageId)}catch(e){}delete tr.imageId;writeDoc('weeks/'+k,S.weeks[k])}}render()}
function saveTrip(trip){const wk=week(trip.date?iso(mondayOf(parseISO(trip.date))):S.ui.weekKey);wk.trips=wk.trips||[];wk.trips.push(trip);const key=iso(mondayOf(parseISO(trip.date)));if(key!==S.ui.weekKey)writeDoc('weeks/'+key,wk);else saveWeek()}
let receiptFile=null;
async function openReceiptScan(){if(!sampleFn){toast('Claude is not available here.');return}const caps=await sampleFn.limits().catch(()=>null);if(!caps||!caps.images){toast('Photo reading is not available on this device.');return}
  openModal(`${mhead('Scan a receipt','Take a photo or choose one. Claude reads the lines; you confirm every line before anything is saved.')}<div class="mb">
    <input type="file" id="rcFile" accept="${esc(caps.images.mediaTypes.join(','))}" capture="environment" style="${fieldCss}">
    <div id="rcPrev"></div>
    <div class="small faint">The photo is only used to read the receipt and is not stored anywhere. Uncertain prices are flagged for you to check.</div><div id="rcOut"></div></div>
    <div class="mf"><button class="btn ghost" data-close>Cancel</button><div class="actions"><button class="btn primary" id="rcGo" disabled>${ICONS.spark} Read receipt</button></div></div>`);
  const fi=document.getElementById('rcFile');fi.onchange=()=>{receiptFile=fi.files[0]||null;document.getElementById('rcGo').disabled=!receiptFile;const p=document.getElementById('rcPrev');p.innerHTML='';if(receiptFile){const u=URL.createObjectURL(receiptFile);const im=document.createElement('img');im.className='thumb';im.src=u;im.onload=()=>URL.revokeObjectURL(u);p.appendChild(im)}};
  document.getElementById('rcGo').onclick=async()=>{if(!receiptFile)return;const out=document.getElementById('rcOut');out.innerHTML='<div class="thinking"><span class="sp"></span>Reading the receipt…</div>';document.getElementById('rcGo').disabled=true;
    try{const j=await sampleFn.json(`This image is a grocery receipt. Extract it faithfully. Reply with only JSON: {"store":string,"date":"YYYY-MM-DD" or "","total":number,"tax":number,"discount":number (total of discounts as a positive number),"lines":[{"text":"<line exactly as printed>","name":"<your best plain-English product name>","qty":number,"price":number (line total after any line discount),"category":"<one of ${CATS.join(', ')}>","uncertain":boolean (true if the price or name is hard to read)}]}. Exclude subtotal, tax, payment and loyalty lines from "lines". Never invent prices; use 0 and uncertain:true if unreadable.`,{images:[receiptFile],cache:false});
      const parsed=parseReceiptResult(j);if(!parsed.ok){out.innerHTML=`<div class="note bad">${esc(parsed.error)} Try a sharper photo, or log the total with Quick entry.</div>`;document.getElementById('rcGo').disabled=false;return}
      receiptFile=null;openReceiptConfirm(parsed)}
    catch(e){out.innerHTML=`<div class="note bad">${aiErr(e)}</div>`;document.getElementById('rcGo').disabled=false}}}
function openReceiptConfirm(parsed){const list=buildList();const m=matchReceiptLines(parsed.lines,list);const st={store:parsed.store||S.settings.store||'',date:parsed.date,total:parsed.total,tax:parsed.tax,discount:parsed.discount,rows:m.rows,notPurchased:m.notPurchased.map(n=>({...n,confirm:true})),note:''};const B=budgetSummary();
  const draw=()=>{const sum=st.rows.filter(r=>r.status!=='skip'&&r.status!=='duplicate').reduce((a,r)=>a+(+r.price||0),0);const stated=st.total!=null?st.total:sum;const mismatch=st.total!=null&&Math.abs(st.total-sum)>0.05;
    document.getElementById('modal').innerHTML=`<div class="overlay"><div class="modal wide" role="dialog" aria-modal="true">${mhead('Confirm the receipt','Nothing is saved until you press Save. Fix names, prices and statuses freely.')}<div class="mb">
      <div class="row"><div class="field"><label for="rStore">Store</label><input id="rStore" value="${esc(st.store)}"></div><div class="field"><label for="rDate">Date</label><input id="rDate" type="date" value="${esc(st.date)}"></div><div class="field"><label for="rTotal">Receipt total</label><input id="rTotal" type="number" step="0.01" value="${st.total!=null?st.total:''}"></div><div class="field"><label for="rTax">Tax</label><input id="rTax" type="number" step="0.01" value="${st.tax||''}"></div><div class="field"><label for="rDisc">Discounts</label><input id="rDisc" type="number" step="0.01" value="${st.discount||''}"></div></div>
      ${mismatch?`<div class="note warn">Lines add up to ${money(sum)} but the receipt total reads ${money(st.total)}. Check for a missed or misread line before saving.</div>`:''}
      <div class="rwrap"><table class="rtable"><thead><tr><th>Line</th><th>Qty</th><th class="num">Actual</th><th class="num">Est.</th><th class="num">Diff</th><th>Status</th><th>For</th><th>Category</th><th></th></tr></thead><tbody>
      ${st.rows.map((r,i)=>`<tr><td class="n"><input data-r="${i}" data-f="name" value="${esc(r.name)}" title="${esc(r.text)}">${r.matchName&&r.status!=='unplanned'?`<div class="small faint">planned: ${esc(r.matchName)}</div>`:r.uncertain?'<div class="small" style="color:var(--warn)">check this line</div>':''}</td><td><input data-r="${i}" data-f="qty" type="number" min="1" value="${r.qty}" style="width:56px"></td><td class="num"><input data-r="${i}" data-f="price" type="number" step="0.01" value="${r.price}" style="width:78px;text-align:right;${r.uncertain?'border-color:var(--warn)':''}"></td><td class="num faint">${r.est!=null?money(r.est):'—'}</td><td class="num diff ${r.est!=null?(r.price>r.est?'up':'down'):''}">${r.est!=null?(r.price-r.est>=0?'+':'−')+money(Math.abs(r.price-r.est)):'—'}</td><td><select data-r="${i}" data-f="status"><option value="planned" ${r.status==='planned'?'selected':''}>Purchased as planned</option><option value="unplanned" ${r.status==='unplanned'?'selected':''}>Unplanned purchase</option><option value="duplicate" ${r.status==='duplicate'?'selected':''}>Possible duplicate</option><option value="skip" ${r.status==='skip'?'selected':''}>Not a grocery line</option></select></td><td><select data-r="${i}" data-f="purpose">${PURPOSES.map(([v,l])=>`<option value="${v}" ${(r.purpose||(r.pet?'pet':'week'))===v?'selected':''}>${l}</option>`).join('')}</select></td><td><select data-r="${i}" data-f="category">${CATS.map(c=>`<option ${c===r.category?'selected':''}>${c}</option>`).join('')}</select><div class="small faint">${r.pet?esc(petName()):esc(r.priority)}</div></td><td><button class="btn icon ghost" data-rm="${i}" aria-label="Remove line">${ICONS.x}</button></td></tr>`).join('')}
      </tbody></table></div>
      <div><button class="btn sm" id="rAdd">${ICONS.plus} Add a line</button></div>
      ${st.notPurchased.length?`<div class="card pad"><div class="eyebrow" style="margin-bottom:6px">On the list but not on this receipt</div><div class="small muted" style="margin-bottom:6px">Tick the ones you really did not buy; they stay unticked on the list. Untick if you bought them elsewhere.</div><div class="checks">${st.notPurchased.map((n,i)=>`<label><input type="checkbox" data-np="${i}" ${n.confirm?'checked':''}>${esc(n.name)} <span class="faint">${money(n.est)}${n.pet?' · '+esc(petName()):''}</span></label>`).join('')}</div></div>`:''}
      <div class="impact"><div class="kv"><span>Lines counted</span><b class="num">${money(sum)}</b></div><div class="kv"><span>Estimate for this week</span><b class="num">${money(B.actual)}</b></div><div class="kv total"><span>Saved as actual total</span><b class="num">${money(stated)}</b></div><div class="kv"><span>${stated>B.actual?'Over estimate':'Under estimate'}</span><b class="num" style="color:${stated>B.actual?'var(--bad)':'var(--good)'}">${money(Math.abs(stated-B.actual))}</b></div><div class="small faint">${esc(petName())}'s lines stay in the Pet category. Long-lasting items count in full here and are spread over their life in the normalized weekly cost.</div></div>
      <div class="field"><label for="rNote">Notes</label><input id="rNote" value="${esc(st.note)}" placeholder="optional"></div></div>
      <div class="mf"><button class="btn ghost" data-close>Discard</button><div class="actions"><button class="btn primary" id="rSave">Save receipt</button></div></div></div></div>`;
    const box=document.querySelector('.modal');
    const readAll=()=>{st.store=document.getElementById('rStore').value.trim();st.date=document.getElementById('rDate').value||iso(today());const tv=parseFloat(document.getElementById('rTotal').value);st.total=isNaN(tv)?null:tv;st.tax=parseFloat(document.getElementById('rTax').value)||0;st.discount=parseFloat(document.getElementById('rDisc').value)||0;st.note=document.getElementById('rNote').value;box.querySelectorAll('[data-r]').forEach(el=>{const r=st.rows[+el.dataset.r];if(!r)return;const f=el.dataset.f;if(f==='price'||f==='qty')r[f]=parseFloat(el.value)||0;else r[f]=el.value});box.querySelectorAll('[data-np]').forEach(cb=>{st.notPurchased[+cb.dataset.np].confirm=cb.checked})};
    box.querySelectorAll('select[data-r]').forEach(s=>s.onchange=()=>{readAll();draw()});box.querySelectorAll('input[data-r][data-f="price"]').forEach(s=>s.onchange=()=>{readAll();draw()});
    box.querySelectorAll('[data-rm]').forEach(b=>b.onclick=()=>{readAll();st.rows.splice(+b.dataset.rm,1);draw()});document.getElementById('rAdd').onclick=()=>{readAll();st.rows.push({text:'',name:'',qty:1,price:0,category:'Other',status:'unplanned',priority:'optional',uncertain:false});draw();const last=box.querySelectorAll('[data-f="name"]');last[last.length-1].focus()};
    document.getElementById('rSave').onclick=()=>{readAll();const rows=st.rows.filter(r=>r.name);const sum2=rows.filter(r=>r.status!=='skip'&&r.status!=='duplicate').reduce((a,r)=>a+(+r.price||0),0);const amount=st.total!=null?st.total:sum2;
      const trip={id:uid('t'),date:st.date,store:st.store,amount:Math.round(amount*100)/100,tax:st.tax,discount:st.discount,note:st.note,method:'scan',estimateAtTime:Math.round(B.actual*100)/100,lines:rows.map(r=>({name:r.name,qty:r.qty,price:Math.round((+r.price||0)*100)/100,category:r.category,status:r.status,canon:r.canon,matchKey:r.matchKey,est:r.est,priority:r.priority,pet:!!r.pet||r.purpose==='pet',purpose:r.purpose||(r.pet?'pet':'week'),famKey:r.famKey,needBase:r.needBase}))};
      const wk=week();wk.checked=wk.checked||{};for(const r of rows)if(r.status==='planned'&&r.matchKey){wk.checked[r.matchKey]=true;const L=list.find(l=>l.key===r.matchKey);if(L)markBought(L,st.date)}for(const n of st.notPurchased)if(n.confirm)delete wk.checked[n.key];
      const nPrices=applyReceiptToPrices(trip);saveTrip(trip);closeModal();toast(`Receipt saved: ${money(trip.amount)} at ${trip.store||'the store'}${nPrices?` · ${nPrices} price${nPrices===1?'':'s'} remembered for future estimates`:''}`)}};
  draw()}
